CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE locale_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),locale text NOT NULL,version integer NOT NULL CHECK(version>0),profile jsonb NOT NULL,active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(locale,version));
CREATE TABLE translation_memory_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),memory_version integer NOT NULL,source_locale text NOT NULL,target_locale text NOT NULL,source_hash text NOT NULL,source_text text NOT NULL,target_text text NOT NULL,approved boolean NOT NULL DEFAULT false,approved_by text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(memory_version,source_locale,target_locale,source_hash));
CREATE TABLE glossary_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version integer UNIQUE NOT NULL CHECK(version>0),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_contents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,content_id text NOT NULL,source_version integer NOT NULL,source_locale text NOT NULL,brand_version integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(content_id,source_version));
CREATE TABLE source_segments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_content_id uuid NOT NULL REFERENCES source_contents(id),segment_id text NOT NULL,kind text NOT NULL,source_text text NOT NULL,start_ms integer,end_ms integer,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_content_id,segment_id));
CREATE TABLE localization_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_key text NOT NULL,source_content_id uuid NOT NULL REFERENCES source_contents(id),target_locale text NOT NULL,version integer NOT NULL,brand_version integer NOT NULL,memory_version integer NOT NULL,glossary_version integer NOT NULL,status text NOT NULL CHECK(status IN('localized','qa_failed','needs_review','approved','rejected','export_ready','released','archived')),fingerprint text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_key,version));
CREATE TABLE localized_segments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES localization_jobs(id),segment_id text NOT NULL,source_text text NOT NULL,target_text text NOT NULL,memory_match text NOT NULL,memory_version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,segment_id));
CREATE TABLE localized_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES localization_jobs(id),format text NOT NULL,payload jsonb NOT NULL,fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,format));
CREATE TABLE localization_qa_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES localization_jobs(id),passed boolean NOT NULL,summary jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE localization_qa_findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),qa_run_id uuid NOT NULL REFERENCES localization_qa_runs(id),code text NOT NULL,severity text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE localization_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES localization_jobs(id),job_version integer NOT NULL,role text NOT NULL CHECK(role IN('language_reviewer','brand_reviewer','cultural_reviewer')),actor text NOT NULL,status text NOT NULL CHECK(status IN('approved','rejected')),note text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,job_version,role));
CREATE TABLE localization_exports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES localization_jobs(id),job_version integer NOT NULL,manifest jsonb NOT NULL,fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,job_version));
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),export_id uuid REFERENCES localization_exports(id),attempt_number integer NOT NULL,status text NOT NULL,next_retry_at timestamptz,error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(export_id,attempt_number));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid,reason text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,entity_type text NOT NULL,entity_id uuid,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_localization_review ON localization_jobs(status,target_locale,updated_at);CREATE INDEX idx_tm_lookup ON translation_memory_entries(source_locale,target_locale,source_hash,approved);CREATE INDEX idx_localization_findings ON localization_qa_findings(code,severity);
